head.script:
scwin.checkEl = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id)) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 CreatePopup1 버튼을 클릭한다.
    //1. In the browser, click the CreatePopup1 button.
    //Verify step 1. The focusTest popup is created.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup1')", "true");
    //Test step 2. CreatePopup2 버튼을 클릭한다.
    //2. Click the CreatePopup2 button.
    //Verify step 2. The focusTest popup is generated.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup2')", "true");
    //Test step 3. CreatePopup3 버튼을 클릭한다.
    //3. Click the CreatePopup3 button.
    //Verify step 3. The focusTest popup is created.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup3')", "true");
    //Test step 4. 생성된 팝업을 임의로 선택한다.
    //4. Select the generated pop-up.
    //Verify step 4. The selected pop-up is activated to the front.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup2').css('z-index') == '6011'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

